type order struct {
	orderDo orderDo

	ALL            field.Asterisk
	ID             field.String
	UserID         field.String
	AddressID      field.String
	VoucherAmount  field.Float64
	DiscountAmount field.Float64
	TotalPrice     field.Float64
	FinalPrice     field.Float64
	Status         field.String
	CreatedAt      field.Time
	UpdatedAt      field.Time
	Vouchers       orderHasManyVouchers

	OrderItems orderHasManyOrderItems

	Payments orderHasManyPayments

	Shipments orderHasManyShipments

	Addresses orderBelongsToAddresses

	Users orderBelongsToUsers

	fieldMap map[string]field.Expr
}

func (o order) Table(newTableName string) *order {
	o.orderDo.UseTable(newTableName)
	return o.updateTableName(newTableName)
}

func (o order) As(alias string) *order {
	o.orderDo.DO = *(o.orderDo.As(alias).(*gen.DO))
	return o.updateTableName(alias)
}

func (o *order) updateTableName(table string) *order {
	o.ALL = field.NewAsterisk(table)
	o.ID = field.NewString(table, "id")
	o.UserID = field.NewString(table, "user_id")
	o.AddressID = field.NewString(table, "address_id")
	o.VoucherAmount = field.NewFloat64(table, "voucher_amount")
	o.DiscountAmount = field.NewFloat64(table, "discount_amount")
	o.TotalPrice = field.NewFloat64(table, "total_price")
	o.FinalPrice = field.NewFloat64(table, "final_price")
	o.Status = field.NewString(table, "status")
	o.CreatedAt = field.NewTime(table, "created_at")
	o.UpdatedAt = field.NewTime(table, "updated_at")

	o.fillFieldMap()

	return o
}

func (o *order) WithContext(ctx context.Context) *orderDo { return o.orderDo.WithContext(ctx) }

func (o order) TableName() string { return o.orderDo.TableName() }

func (o order) Alias() string { return o.orderDo.Alias() }

func (o order) Columns(cols ...field.Expr) gen.Columns { return o.orderDo.Columns(cols...) }

func (o *order) GetFieldByName(fieldName string) (field.OrderExpr, bool) {
	_f, ok := o.fieldMap[fieldName]
	if !ok || _f == nil {
		return nil, false
	}
	_oe, ok := _f.(field.OrderExpr)
	return _oe, ok
}

func (o *order) fillFieldMap() {
	o.fieldMap = make(map[string]field.Expr, 16)
	o.fieldMap["id"] = o.ID
	o.fieldMap["user_id"] = o.UserID
	o.fieldMap["address_id"] = o.AddressID
	o.fieldMap["voucher_amount"] = o.VoucherAmount
	o.fieldMap["discount_amount"] = o.DiscountAmount
	o.fieldMap["total_price"] = o.TotalPrice
	o.fieldMap["final_price"] = o.FinalPrice
	o.fieldMap["status"] = o.Status
	o.fieldMap["created_at"] = o.CreatedAt
	o.fieldMap["updated_at"] = o.UpdatedAt

}

func (o order) clone(db *gorm.DB) order {
	o.orderDo.ReplaceConnPool(db.Statement.ConnPool)
	o.Vouchers.db = db.Session(&gorm.Session{Initialized: true})
	o.Vouchers.db.Statement.ConnPool = db.Statement.ConnPool
	o.OrderItems.db = db.Session(&gorm.Session{Initialized: true})
	o.OrderItems.db.Statement.ConnPool = db.Statement.ConnPool
	o.Payments.db = db.Session(&gorm.Session{Initialized: true})
	o.Payments.db.Statement.ConnPool = db.Statement.ConnPool
	o.Shipments.db = db.Session(&gorm.Session{Initialized: true})
	o.Shipments.db.Statement.ConnPool = db.Statement.ConnPool
	o.Addresses.db = db.Session(&gorm.Session{Initialized: true})
	o.Addresses.db.Statement.ConnPool = db.Statement.ConnPool
	o.Users.db = db.Session(&gorm.Session{Initialized: true})
	o.Users.db.Statement.ConnPool = db.Statement.ConnPool
	return o
}

func (o order) replaceDB(db *gorm.DB) order {
	o.orderDo.ReplaceDB(db)
	o.Vouchers.db = db.Session(&gorm.Session{})
	o.OrderItems.db = db.Session(&gorm.Session{})
	o.Payments.db = db.Session(&gorm.Session{})
	o.Shipments.db = db.Session(&gorm.Session{})
	o.Addresses.db = db.Session(&gorm.Session{})
	o.Users.db = db.Session(&gorm.Session{})
	return o
}

